const S = 80;
const CLRS = "6b2737-e08e45-f8f4a6-bdf7b7-3943b7"
  .split("-")
  .map((i) => "#" + i);
const BG = "#000008";

function setup() {
  createCanvas(400, 400);
	describe("animation of randomly generated colored arc (from top left circle) ordered in a grid")
  frameRate(60);
  noStroke();
  background(BG);
}

function draw() {
  if (frameCount % 15 > 0) return;

  const x = S / 2 + S * ~~random(width / S);
  const y = S / 2 + S * ~~random(height / S);
  drawTile(x, y, S);

  push();
  stroke(0);
  fill(255);
  text("#minacoding 24/02 Color", 0, 10);
  pop();
}

function drawTile(x, y, S) {
  push();
  translate(x, y);
  fill(BG);
  rectMode(CENTER);
  rect(0, 0, S);
  rotate(~~random(4) * HALF_PI);
  translate(S / 2, S / 2);
  fill(random(CLRS));
  arc(0, 0, S * 2, S * 2, PI, TWO_PI - HALF_PI);
	if (random() < 0.4) {
		fill(random(CLRS));
		arc(0, 0, S, S, PI, TWO_PI - HALF_PI);		
	}
  pop();
}
